const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const heights = input.slice(1, n + 1);
const maxHeight = Math.max(...heights);
const deficits = heights.map(height => maxHeight - height);
const maxDeficit = Math.max(...deficits);

let phases = 0;

for (let level = 1; level <= maxDeficit; level++) {
  for (let i = 0; i < n; i++) {
    if (deficits[i] >= level && (i === 0 || deficits[i - 1] < level)) {
      phases++;
    }
  }
}

console.log(phases);
